t = int(input())
for i in range(t):
	(n, h) = map(int, input().split())
	x = list(map(int, input().split()))
	h1 = list(map(int, input().split()))
	for j in range(n):
		h1[j] = h1[j] - h
	c = 0
	for k in range(n):
		if x[k] <= h1[k]:
			print(-1)
			c = 1
			break
	ans = 0
	for z in range(n):
		if (h1[z] + x[z] + 2) / 2 > ans:
			ans = (h1[z] + x[z] + 2) / 2
	if c == 0:
		print(int(ans))
